examples.template:
NavigationStack {
    ScrollView {
        VStack(alignment: .leading, spacing: theme.spacing.space4) {
            Text({{description}})
                .monarchTextStyle(.body)
                .foregroundStyle(theme.colors.textMuted)
            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: theme.spacing.space2) {
                    MonarchPeriodSelector(selection: $period, today: {{today|date}})
                    Toggle({{arrange}}, isOn: $isEditing)
                        .toggleStyle(.monarchButton(.outline, size: .sm))
                }
            }
            LazyVGrid(
                columns: Array(
                    repeating: GridItem(.flexible(), spacing: theme.spacing.space3),
                    count: dynamicTypeSize.isAccessibilitySize ? 1 : 2
                ),
                spacing: theme.spacing.space3
            ) {
                MonarchStatCard(
                    {{kpis.0.label}},
                    value: {{kpis.0.value|double}},
                    format: .currency(code: {{kpis.0.currency}}),
                    isCompact: true
                )
                MonarchStatCard({{kpis.1.label}}, value: {{kpis.1.value|double}})
                MonarchStatCard(
                    {{kpis.2.label}},
                    value: {{kpis.2.value|double}},
                    change: MonarchMetricChange({{kpis.2.change.value|double}}, comparison: {{kpis.2.change.comparison}}),
                    format: .percent
                )
                MonarchStatCard({{kpis.3.label}}, value: {{kpis.3.value|double}})
            }
            MonarchInsightStrip(
                {{sections.insights}},
                insights: [
                    MonarchInsight(
                        id: {{insight.id}},
                        title: {{insight.title}},
                        why: {{insight.why}},
                        tone: {{insight.severity|tone}},
                        origin: {{insight.origin|case}},
                        actionTitle: {{insight.action}},
                        action: {}
                    )
                ]
            )
            MonarchDashboardGrid(
                HomeSection.allCases,
                layout: $layout,
                itemLabel: \.rawValue,
                span: { $0.span },
                isEditing: isEditing,
                labels: MonarchDashboardGridLabels(label: "Dashboard sections"),
                content: { section in
                    switch section {
                    case .pipeline:
                        MonarchWidget({{sections.pipeline}}) {
                            MonarchFunnelChart(
                                {{pipeline.title}},
                                stages: [
                                    MonarchFunnelChartStage({{pipeline.stages.0.label}}, value: {{pipeline.stages.0.value|double}}, key: {{pipeline.stages.0.key}}),
                                    MonarchFunnelChartStage({{pipeline.stages.1.label}}, value: {{pipeline.stages.1.value|double}}, key: {{pipeline.stages.1.key}}),
                                    MonarchFunnelChartStage({{pipeline.stages.2.label}}, value: {{pipeline.stages.2.value|double}}, key: {{pipeline.stages.2.key}}),
                                ]
                            )
                        }
                    case .today:
                        MonarchWidget({{sections.today}}, description: {{agenda.dateLabel}}) {
                            LabeledContent({{agenda.tasks.0.title}}) {
                                if {{agenda.tasks.0.overdue}} {
                                    MonarchBadge("Overdue", tone: .danger)
                                }
                            }
                            Text({{agenda.tasks.1.title}})
                        }
                    case .followUps:
                        MonarchWidget({{sections.followUps}}, content: {
                            LabeledContent({{followUps.0.label}}, value: {{followUps.0.value}})
                            LabeledContent({{followUps.1.label}}, value: {{followUps.1.value}})
                        })
                    case .upcoming:
                        MonarchWidget({{sections.upcoming}}) {
                            LabeledContent({{upcoming.0.label}}, value: {{upcoming.0.value}})
                            LabeledContent({{upcoming.1.label}}, value: {{upcoming.1.value}})
                        }
                    case .performance:
                        MonarchWidget({{sections.performance}}) {
                            MonarchBarChart(
                                {{performance.title}},
                                categories: [{{performance.data.0.month}}, {{performance.data.1.month}}, {{performance.data.2.month}}, {{performance.data.3.month}}],
                                series: [
                                    MonarchBarChartSeries("won", label: {{performance.title}}, values: [{{performance.data.0.won|double}}, {{performance.data.1.won|double}}, {{performance.data.2.won|double}}, {{performance.data.3.won|double}}]),
                                ],
                                description: {{performance.description}}
                            )
                        }
                    case .leaders:
                        MonarchWidget({{sections.leaders}}) {
                            MonarchLeaderboard(
                                [
                                    MonarchLeaderboardEntry({{leaders.entries.0.name}}, value: {{leaders.entries.0.value|double}}, id: {{leaders.entries.0.id}}, secondary: {{leaders.entries.0.secondary}}),
                                    MonarchLeaderboardEntry({{leaders.entries.1.name}}, value: {{leaders.entries.1.value|double}}, id: {{leaders.entries.1.id}}, secondary: {{leaders.entries.1.secondary}}),
                                    MonarchLeaderboardEntry({{leaders.entries.2.name}}, value: {{leaders.entries.2.value|double}}, id: {{leaders.entries.2.id}}, secondary: {{leaders.entries.2.secondary}}),
                                ],
                                label: {{sections.leaders}},
                                valueLabel: {{leaders.valueLabel}},
                                sort: .descending
                            )
                        }
                    case .activity:
                        MonarchWidget({{sections.activity}}, content: {
                            MonarchActivityTimeline(
                                [
                                    MonarchActivityTimelineEvent(
                                        id: {{activity.0.id}},
                                        actor: MonarchActivityTimelineActor({{activity.0.actor}}),
                                        verb: {{activity.0.verb}},
                                        object: {{activity.0.object}},
                                        time: {{activity.0.time|date}}
                                    ),
                                    MonarchActivityTimelineEvent(
                                        id: {{activity.1.id}},
                                        actor: MonarchActivityTimelineActor({{activity.1.actor}}),
                                        verb: {{activity.1.verb}},
                                        object: {{activity.1.object}},
                                        time: {{activity.1.time|date}}
                                    ),
                                ],
                                isGroupedByDay: false,
                                density: .compact,
                                now: now
                            )
                        })
                    }
                }
            )
            .labeledContentStyle(.monarch)
        }
        .padding(theme.spacing.space4)
    }
    .monarchCanvas()
    .navigationTitle({{title}})
    #if os(iOS)
    .navigationBarTitleDisplayMode(.inline)
    #endif
}
.environment(\.locale, Locale(identifier: {{locale}}))
.environment(\.timeZone, TimeZone(identifier: {{timeZone}}) ?? .gmt)
.frame(maxWidth: .infinity, minHeight: theme.spacing.space24 * 8)

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@Environment(\.dynamicTypeSize) private var dynamicTypeSize
@State private var period = MonarchPeriod(.last7Days)
@State private var layout: [String] = []
@State private var isEditing = false
private let now = {{now|date}}

/// The sections of the home screen, in their default order.
enum HomeSection: String, CaseIterable, Identifiable {
    case pipeline, today, followUps, upcoming, performance, leaders, activity

    var id: String { rawValue }

    /// Columns on an iPad; every section is full width on a phone.
    var span: MonarchDashboardGridSpan {
        switch self {
        case .pipeline: .two
        case .performance: .two
        default: .one
        }
    }
}

