NavigationStack {
    ScrollView {
        VStack(alignment: .leading, spacing: theme.spacing.space4) {
            Text("Sales · UK and Ireland")
                .monarchTextStyle(.body)
                .foregroundStyle(theme.colors.textMuted)
            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: theme.spacing.space2) {
                    MonarchPeriodSelector(selection: $period, today: Date(timeIntervalSince1970: 1_781_481_600))
                    Toggle("Arrange", isOn: $isEditing)
                        .toggleStyle(.monarchButton(.outline, size: .sm))
                }
            }
            LazyVGrid(
                columns: Array(
                    repeating: GridItem(.flexible(), spacing: theme.spacing.space3),
                    count: dynamicTypeSize.isAccessibilitySize ? 1 : 2
                ),
                spacing: theme.spacing.space3
            ) {
                MonarchStatCard(
                    "Pipeline value",
                    value: 1_200_000.0,
                    format: .currency(code: "GBP"),
                    isCompact: true
                )
                MonarchStatCard("Open deals", value: 86.0)
                MonarchStatCard(
                    "Win rate",
                    value: 0.27,
                    change: MonarchMetricChange(0.03, comparison: "vs last quarter"),
                    format: .percent
                )
                MonarchStatCard("Closing in June", value: 14.0)
            }
            MonarchInsightStrip(
                "Insights",
                insights: [
                    MonarchInsight(
                        id: "stale",
                        title: "6 deals have had no activity for 14 days",
                        why: "All six are in Proposal.",
                        tone: .warning,
                        origin: .rule,
                        actionTitle: "Show deals",
                        action: {}
                    )
                ]
            )
            MonarchDashboardGrid(
                HomeSection.allCases,
                layout: $layout,
                itemLabel: \.rawValue,
                span: { $0.span },
                isEditing: isEditing,
                labels: MonarchDashboardGridLabels(label: "Dashboard sections"),
                content: { section in
                    switch section {
                    case .pipeline:
                        MonarchWidget("Pipeline") {
                            MonarchFunnelChart(
                                "Deals by stage",
                                stages: [
                                    MonarchFunnelChartStage("Lead", value: 240.0, key: "lead"),
                                    MonarchFunnelChartStage("Qualified", value: 120.0, key: "qualified"),
                                    MonarchFunnelChartStage("Proposal", value: 48.0, key: "proposal"),
                                ]
                            )
                        }
                    case .today:
                        MonarchWidget("Today", description: "Monday 15 June") {
                            LabeledContent("Send the Harbor Labs proposal") {
                                if true {
                                    MonarchBadge("Overdue", tone: .danger)
                                }
                            }
                            Text("Call Globex about the pilot")
                        }
                    case .followUps:
                        MonarchWidget("Waiting on you", content: {
                            LabeledContent("Mei Chen, Globex", value: "Replied 2 days ago")
                            LabeledContent("Ana Lopez, Harbor Labs", value: "Replied yesterday")
                        })
                    case .upcoming:
                        MonarchWidget("Coming up") {
                            LabeledContent("Demo with Globex", value: "Tue 16 Jun, 14:00")
                            LabeledContent("Harbor Labs expected to close", value: "Fri 26 Jun")
                        }
                    case .performance:
                        MonarchWidget("Performance") {
                            MonarchBarChart(
                                "Deals won",
                                categories: ["Mar", "Apr", "May", "Jun"],
                                series: [
                                    MonarchBarChartSeries("won", label: "Deals won", values: [8.0, 11.0, 9.0, 13.0]),
                                ],
                                description: "By month"
                            )
                        }
                    case .leaders:
                        MonarchWidget("Top performers") {
                            MonarchLeaderboard(
                                [
                                    MonarchLeaderboardEntry("Amara Okafor", value: 9.0, id: "amara", secondary: "Enterprise"),
                                    MonarchLeaderboardEntry("Lucas Martin", value: 6.0, id: "lucas", secondary: "Mid-market"),
                                    MonarchLeaderboardEntry("Mei Chen", value: 3.0, id: "mei", secondary: "Mid-market"),
                                ],
                                label: "Top performers",
                                valueLabel: "Deals won",
                                sort: .descending
                            )
                        }
                    case .activity:
                        MonarchWidget("Recent activity", content: {
                            MonarchActivityTimeline(
                                [
                                    MonarchActivityTimelineEvent(
                                        id: "e1",
                                        actor: MonarchActivityTimelineActor("Lucas Martin"),
                                        verb: "moved",
                                        object: "Harbor Labs to Proposal",
                                        time: Date(timeIntervalSince1970: 1_781_516_400)
                                    ),
                                    MonarchActivityTimelineEvent(
                                        id: "e2",
                                        actor: MonarchActivityTimelineActor("Amara Okafor"),
                                        verb: "won",
                                        object: "Northwind renewal",
                                        time: Date(timeIntervalSince1970: 1_781_510_700)
                                    ),
                                ],
                                isGroupedByDay: false,
                                density: .compact,
                                now: now
                            )
                        })
                    }
                }
            )
            .labeledContentStyle(.monarch)
        }
        .padding(theme.spacing.space4)
    }
    .monarchCanvas()
    .navigationTitle("Home")
    #if os(iOS)
    .navigationBarTitleDisplayMode(.inline)
    #endif
}
.environment(\.locale, Locale(identifier: "en-GB"))
.environment(\.timeZone, TimeZone(identifier: "Europe/London") ?? .gmt)
.frame(maxWidth: .infinity, minHeight: theme.spacing.space24 * 8)

